     1→/**
     2→ * Focusable Component
     3→ *
     4→ * A wrapper component that makes any child focusable on TV platforms
     5→ * with consistent focus behavior and styling
     6→ */
     7→
     8→import React, { useCallback, useState, forwardRef } from 'react';
     9→import { TouchableOpacity, View, ViewStyle, Platform } from 'react-native';
    10→import Animated, {
    11→  useSharedValue,
    12→  useAnimatedStyle,
    13→  withTiming,
    14→} from 'react-native-reanimated';
    15→import { TV_FOCUS_CONFIG } from '../../utils/tvStyles/focus';
    16→
    17→const AnimatedTouchableOpacity = Animated.createAnimatedComponent(TouchableOpacity);
    18→
    19→export interface FocusableProps {
    20→  children: React.ReactNode;
    21→  onPress?: () => void;
    22→  onFocus?: () => void;
    23→  onBlur?: () => void;
    24→  hasTVPreferredFocus?: boolean;
    25→  style?: ViewStyle | ViewStyle[];
    26→  focusedStyle?: ViewStyle;
    27→  disabled?: boolean;
    28→  testID?: string;
    29→  accessibilityLabel?: string;
    30→  accessibilityHint?: string;
    31→  variant?: 'default' | 'card' | 'button';
    32→  enableScale?: boolean;
    33→  enableGlow?: boolean;
    34→  enableBorder?: boolean;
    35→  borderRadius?: number;
    36→}
    37→
    38→/**
    39→ * Focusable wrapper component for TV platforms
    40→ * Provides consistent focus behavior and styling
    41→ */
    42→const Focusable = forwardRef<TouchableOpacity, FocusableProps>(
    43→  (
    44→    {
    45→      children,
    46→      onPress,
    47→      onFocus,
    48→      onBlur,
    49→      hasTVPreferredFocus = false,
    50→      style,
    51→      focusedStyle,
    52→      disabled = false,
    53→      testID,
    54→      accessibilityLabel,
    55→      accessibilityHint,
    56→      variant = 'default',
    57→      enableScale = false,
    58→      enableGlow = false,
    59→      enableBorder = false,
    60→      borderRadius,
    61→    },
    62→    ref
    63→  ) => {
    64→    const [isFocused, setIsFocused] = useState(false);
    65→
    66→    // Animation values
    67→    const scale = useSharedValue(1);
    68→    const glowOpacity = useSharedValue(0);
    69→
    70→    const handleFocus = useCallback(() => {
    71→      setIsFocused(true);
    72→
    73→      if (enableScale) {
    74→        scale.value = withTiming(TV_FOCUS_CONFIG.focusScale, {
    75→          duration: TV_FOCUS_CONFIG.focusAnimationDuration,
    76→        });
    77→      }
    78→
    79→      if (enableGlow) {
    80→        glowOpacity.value = withTiming(1, {
    81→          duration: TV_FOCUS_CONFIG.focusAnimationDuration,
    82→        });
    83→      }
    84→
    85→      onFocus?.();
    86→    }, [onFocus, enableScale, enableGlow]);
    87→
    88→    const handleBlur = useCallback(() => {
    89→      setIsFocused(false);
    90→
    91→      if (enableScale) {
    92→        scale.value = withTiming(1, {
    93→          duration: TV_FOCUS_CONFIG.focusAnimationDuration,
    94→        });
    95→      }
    96→
    97→      if (enableGlow) {
    98→        glowOpacity.value = withTiming(0, {
    99→          duration: TV_FOCUS_CONFIG.focusAnimationDuration,
   100→        });
   101→      }
   102→
   103→      onBlur?.();
   104→    }, [onBlur, enableScale, enableGlow]);
   105→
   106→    const handlePress = useCallback(() => {
   107→      if (!disabled && onPress) {
   108→        onPress();
   109→      }
   110→    }, [disabled, onPress]);
   111→
   112→    // Merge base styles
   113→    const baseStyle: ViewStyle = Array.isArray(style) ? Object.assign({}, ...style) : { ...style };
   114→
   115→    // Add border radius if specified
   116→    if (borderRadius !== undefined) {
   117→      baseStyle.borderRadius = borderRadius;
   118→    }
   119→
   120→    // Add focus-specific styles
   121→    if (isFocused && focusedStyle) {
   122→      Object.assign(baseStyle, focusedStyle);
   123→    }
   124→
   125→    // Add TV focus border when focused and enabled
   126→    if (Platform.isTV && isFocused && enableBorder) {
   127→      baseStyle.borderWidth = TV_FOCUS_CONFIG.focusBorderWidth;
   128→      baseStyle.borderColor = TV_FOCUS_CONFIG.focusBorderColor;
   129→    }
   130→
   131→    // Animated styles for scale
   132→    const animatedStyle = useAnimatedStyle(() => ({
   133→      transform: enableScale ? [{ scale: scale.value }] : [],
   134→    }));
   135→
   136→    if (!onPress) {
   137→      // Non-interactive focusable (View only)
   138→      return (
   139→        <View
   140→          style={[baseStyle]}
   141→          testID={testID}
   142→          accessible={true}
   143→          accessibilityLabel={accessibilityLabel}
   144→          // @ts-ignore - TV-specific props
   145→          onFocus={handleFocus}
   146→          onBlur={handleBlur}
   147→          hasTVPreferredFocus={Platform.isTV ? hasTVPreferredFocus : undefined}
   148→        >
   149→          {children}
   150→        </View>
   151→      );
   152→    }
   153→
   154→    // Interactive focusable with animations (if enabled)
   155→    if (enableScale) {
   156→      return (
   157→        <AnimatedTouchableOpacity
   158→          // @ts-ignore - ref type mismatch
   159→          ref={ref}
   160→          style={[baseStyle, animatedStyle]}
   161→          onPress={handlePress}
   162→          onFocus={handleFocus}
   163→          onBlur={handleBlur}
   164→          disabled={disabled}
   165→          activeOpacity={0.7}
   166→          testID={testID}
   167→          accessible={true}
   168→          accessibilityLabel={accessibilityLabel}
   169→          accessibilityHint={accessibilityHint}
   170→          accessibilityRole="button"
   171→          // @ts-ignore - TV-specific props
   172→          hasTVPreferredFocus={Platform.isTV ? hasTVPreferredFocus : undefined}
   173→          isTVSelectable={Platform.isTV ? !disabled : undefined}
   174→        >
   175→          {children}
   176→        </AnimatedTouchableOpacity>
   177→      );
   178→    }
   179→
   180→    // Interactive focusable without animations (standard)
   181→    return (
   182→      <TouchableOpacity
   183→        ref={ref}
   184→        style={baseStyle}
   185→        onPress={handlePress}
   186→        onFocus={handleFocus}
   187→        onBlur={handleBlur}
   188→        disabled={disabled}
   189→        activeOpacity={0.7}
   190→        testID={testID}
   191→        accessible={true}
   192→        accessibilityLabel={accessibilityLabel}
   193→        accessibilityHint={accessibilityHint}
   194→        accessibilityRole="button"
   195→        // @ts-ignore - TV-specific props
   196→        hasTVPreferredFocus={Platform.isTV ? hasTVPreferredFocus : undefined}
   197→        isTVSelectable={Platform.isTV ? !disabled : undefined}
   198→      >
   199→        {children}
   200→      </TouchableOpacity>
   201→    );
   202→  }
   203→);
   204→
   205→Focusable.displayName = 'Focusable';
   206→
   207→export default Focusable;
